comparison=[['Modelo','F1 val.','Acc. test','Bal. acc.','F1 test']]+[[r['Modelo'],f"{r['validation_f1']:.4f}",f"{r['Accuracy (%)']:.2f}%",f"{r['Balanced Acc (%)']:.2f}%",f"{r['F1 Macro']:.4f}"] for r in sorted(M['comparison_table'],key=lambda x:x['F1 Macro'],reverse=True)]
